lemma.raw:
\label{lemma:1}

Let $\snri{i}$ and $\snri{j}$ be statistically independent and not
necessarily identically distributed (i.n.i.d.) exponential random
variables with hazard rate $\snravei{i}$ and $\snravei{j}$,
respectively. Suppose that the ratio of $Z$ takes the form


\begin{align}
    Z=\frac{\snri{i} \snri{j}}{\snri{i} +2\snri{j}}
\end{align}


Then, we obtain the PDF of random variable $Z$ as


\begin{align} \label{eq:PDF:Z:1}
    \PDF{Z}{z}
    =
    \alpha z \exp\left(-\beta_i z\right)
    \left[\alpha\Bessel{0}{\alpha z} + \beta_i \Bessel{1}{\alpha z}\right]
\end{align}


where $\alpha = 2\sqrt{\frac{2}{\snravei{i}\snravei{j}}}$ and
$\beta_i = \frac{1}{\snravei{j}} + \frac{2}{\snravei{i}}$.
\begin{proof}


Let us rewrite $Z$ in a more tractable form as


\begin{align} \label{eq:Z}
    Z
    =
    \left(X + Y\right)^{-1}
\end{align}


where $X=1/\snri{i}$ and $Y=2/\snri{j}$. Then, after some algebraic
simplifications together with the help of
\cite[eq.~(3.471.9)]{GR:00:Book}, the moment generating function
(MGF) of $X$ and $Y$ can be expressed as, respectively


\begin{align} \label{eq:MGF:X}
    &\MGF{X}{s}
    =
    \EXs{X}{\exp\left(-s x\right)}
    =
    2 \sqrt{\frac{s}{\snravei{i}}} \Bessel{1}{2
    \sqrt{\frac{s}{\snravei{i}}}}
    \\ \label{eq:MGF:Y}
    &\MGF{Y}{s}
    =
    \EXs{Y}{\exp\left(-s y\right)}
    =
    2 \sqrt{\frac{2s}{\snravei{j}}} \Bessel{1}{2
    \sqrt{\frac{2s}{\snravei{j}}}}
\end{align}




As can be seen from \eqref{eq:Z}, since $1/Z$ is the sum of two
statistically independent random variables, by using
\eqref{eq:MGF:X} and \eqref{eq:MGF:Y}, the MGF of $1/Z$ can be
expressed as


\begin{align} \label{eq:MGF:1:Z}
    \MGF{1/Z}{s}
    =
    4\sqrt{\frac{2}{\snravei{i}\snravei{j}}}s \Bessel{1}{2
    \sqrt{\frac{s}{\snravei{i}}}}
    \Bessel{1}{2
    \sqrt{\frac{2s}{\snravei{j}}}}
\end{align}


Then, the cumulative distribution function (CDF) of $1/Z$,
$\CDF{1/Z}{x}$, can be shown as


\begin{eqnarray} \label{eq:CDF:1:Z}
    \CDF{1/Z}{x}
     =1- \mathcal{L}^{-1}\{\MGF{1/Z}{s}/s\}|_{1/x}
\end{eqnarray}


where $\mathcal{L}^{-1}\{.\}$ stands for the inverse Laplace
transform. From \eqref{eq:MGF:1:Z} and \eqref{eq:CDF:1:Z} together
with \cite[eq.~(13.2.20)]{RK:66:Book}, we have



\begin{align} \label{eq:CDF:Z:1}
    \CDF{Z}{z}
    =
    1 - \alpha z \exp\left(-\beta_i z\right)
    \Bessel{1}{\alpha z}
\end{align}


where $\alpha = 2\sqrt{\frac{2}{\snravei{i}\snravei{j}}}$ and
$\beta_i = \frac{1}{\snravei{j}} + \frac{2}{\snravei{i}}$. By
differentiating \eqref{eq:CDF:Z:1} with respect to $z$ and using the
fact that
$\tfrac{d\Bessel{v}{z}}{dz}=-\Bessel{v-1}{z}-\tfrac{v}{z}\Bessel{v}{z}$
\cite[eq.~(8.486.12)]{GR:00:Book}, we obtain \eqref{eq:PDF:Z:1}
which completes the proof.
\end{proof}

\label{lemma:2}
Let $\snri{0}$, $\snri{1}$, and $\snri{2}$ be the three i.n.i.d.
exponential random variables with hazard rates $\snravei{0}$,
$\snravei{1}$, and $\snravei{2}$, respectively, then the PDF of
$T=\snri{0}\frac{\snri{1}+\snri{2}}{\snri{1}\snri{2}}$ is given by


\begin{align} \label{eq:PDF:T:1}
    \PDF{T}{t}
    =
    \! \!
    \sum\limits_{n=1}^2
    \xi_n
    \tfrac{1}{(t+\zeta)^{3+n}}

    {_2}F_1\left(3+n,n+\tfrac{1}{2};\tfrac{7}{2};\tfrac{t+\eta}{t+\zeta}\right)
\end{align}


where


\begin{align*}
    \xi_n 
    &=
    \sqrt{\pi}
    \left(\frac{4}{\sqrt{\snravei{1}\snravei{2}}}\right)^{n}
    \frac{\Gamma\left(3+n\right)\Gamma\left(3-n\right)}{\Gamma\left(7/2\right)}
    \varpi_n
    \nonumber
    \\
    \varpi_0 
    &=
    \frac{4}{\snravei{0}\snravei{1}\snravei{2}},
    \hspace{0.5cm}
    \varpi_1
    =
    \frac{2\left(\snravei{1}+\snravei{2}\right)}{\snravei{0}\left(\snravei{1}\snravei{2}\right)^{3/2}}
    \nonumber
    \\
    \zeta 
    &=
    \snravei{0} \left(\frac{1}{\snravei{1}} + \frac{1}{\snravei{2}} +
    \frac{2}{\snravei{1}\snravei{2}}\right),
    \hspace{0.3cm}


    \eta 

    =
    \snravei{0} \left(\frac{1}{\snravei{1}} + \frac{1}{\snravei{2}} - \frac{2}{\snravei{1}\snravei{2}}\right)
\end{align*}


and $_2F_1\left(a,b;c;z\right)$ is the Gauss hypergeometric function
\cite[eq.~(2.12.1)]{Erd:53:Book}.

\begin{proof} Since $T=\snri{0}\frac{\snri{1}+\snri{2}}{\snri{1}\snri{2}}$, by defining $W=\frac{\snri{1}\snri{2}}{\snri{1}+\snri{2}}$, we have


\begin{align} \label{eq:CDF:T:1}
    \CDF{T}{t}
    =


    \int\nolimits_{0}^{\infty}
    \left[1-\exp\left(-\frac{wt}{\snravei{0}}\right)\right]
    \PDF{W}{w} dw
\end{align}


Following similar steps as in Lemma~\ref{lemma:1}, we obtain
$\PDF{W}{w}$ as


\begin{align} \label{eq:PDF:W:1}
    &\PDF{W}{w}
    =
    \frac{2w}{\snravei{1}\snravei{2}}
    \exp\left[-\left(\frac{1}{\snravei{1}}+\frac{1}{\snravei{2}}\right)w\right]
    \nonumber
    \\
    &\times
    \left[
    2\Bessel{0}{\frac{2w}{\sqrt{\snravei{1}\snravei{2}}}}
    +
    \left(\frac{\snravei{1}+\snravei{2}}{\snravei{1}\snravei{2}}\right)
    \Bessel{1}{\frac{2w}{\sqrt{\snravei{1}\snravei{2}}}}
    \right]
\end{align}


By substituting \eqref{eq:PDF:W:1} in \eqref{eq:CDF:T:1} and taking
the derivative with respect to $t$, we obtain the PDF of $T$ as


\begin{align} \label{eq:PDF:T:2}
    \PDF{T}{t}
    =
    \sum\limits_{n=1}^{2}
    \varpi_n
    \int\limits_{0}^{\infty}
    w^2
    &\exp\left[-\left(\frac{t}{\snravei{0}}+\frac{1}{\snravei{1}}+\frac{1}{\snravei{2}}\right)w\right]
    \nonumber
    \\
    &\times
    \Bessel{n}{\frac{2w}{\sqrt{\snravei{1}\snravei{2}}}}
    dw
\end{align}


It is observed that the integral given in \eqref{eq:PDF:T:2} can be
simplified by using \cite[eq.~(6.621.3)]{Prudnikov:90:Book} which
results in \eqref{eq:PDF:T:1}. This completes the proof.
\end{proof}

